const itineraryData = [
  {
    id: 'place-1',
    name: '해변 산책',
    region: '서귀포시',
    type: '야외',
    photo: 'assets/reference/photo-1.png',
    day: 1
  },
  {
    id: 'place-2',
    name: '오래된 골목 카페',
    region: '제주시',
    type: '카페',
    photo: 'assets/reference/photo-2.png',
    day: 1
  },
  {
    id: 'place-3',
    name: '오름 전망대',
    region: '성산군',
    type: '경관',
    photo: 'assets/reference/photo-3.png',
    day: 2
  },
  {
    id: 'place-4',
    name: '저녁 시장',
    region: '서귀포시',
    type: '식도락',
    photo: 'assets/reference/photo-fragment.png',
    day: 2
  }
];

function renderStaticView() {
  const listEl = document.getElementById('itinerary-list');
  if (!listEl) return;

  let currentDay = null;
  const fragment = document.createDocumentFragment();

  itineraryData.forEach((place, index) => {
    if (place.day !== currentDay) {
      currentDay = place.day;
      const heading = document.createElement('h2');
      heading.className = 'day-heading';
      heading.id = `day-${currentDay}-heading`;
      heading.textContent = `Day ${currentDay}`;
      fragment.appendChild(heading);
    }

    const row = document.createElement('div');
    row.className = 'place-row';
    row.id = `row-${place.id}`;

    const checkboxWrapper = document.createElement('label');
    checkboxWrapper.className = 'checkbox-wrapper';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = `check-${place.id}`;
    checkbox.disabled = true;
    checkboxWrapper.appendChild(checkbox);

    const media = document.createElement('div');
    media.className = 'place-media';
    const img = document.createElement('img');
    img.src = place.photo;
    img.alt = place.name + ' 사진';
    img.loading = 'lazy';
    media.appendChild(img);

    const info = document.createElement('div');
    info.className = 'place-info';
    const name = document.createElement('div');
    name.className = 'place-name';
    name.id = `name-${place.id}`;
    name.textContent = place.name;
    const meta = document.createElement('div');
    meta.className = 'place-meta';
    meta.textContent = `${place.region} · ${place.type}`;
    info.appendChild(name);
    info.appendChild(meta);

    const handle = document.createElement('button');
    handle.className = 'reorder-handle';
    handle.type = 'button';
    handle.disabled = true;
    handle.id = `handle-${place.id}`;
    const gripImg = document.createElement('img');
    gripImg.src = 'assets/icons/GripVertical.svg';
    gripImg.alt = '순서 변경';
    gripImg.width = 16;
    gripImg.height = 16;
    handle.appendChild(gripImg);

    row.appendChild(checkboxWrapper);
    row.appendChild(media);
    row.appendChild(info);
    row.appendChild(handle);
    fragment.appendChild(row);
  });

  listEl.appendChild(fragment);
}

completed.layout:
:root {
  --color-bg: #ffffff;
  --color-text-primary: #111111;
  --color-text-secondary: #666666;
  --color-border: #e0e0e0;
  --color-pill-bg: #f5f5f5;
  --color-pill-active-bg: #111111;
  --color-pill-active-text: #ffffff;
  --color-row-bg: #fafafa;
  --color-btn-disabled-bg: #e0e0e0;
  --color-btn-disabled-text: #999999;

  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";

  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-pill: 999px;

  --max-width: 430px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  color: var(--color-text-primary);
  background-color: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#app {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: var(--space-lg) var(--space-md);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.header {
  margin-bottom: var(--space-lg);
  text-align: center;
}

#page-title {
  font-size: 24px;
  font-weight: 700;
  margin: 0;
  letter-spacing: -0.02em;
}

.destination-pills {
  display: flex;
  justify-content: center;
  gap: var(--space-sm);
  margin-bottom: var(--space-lg);
}

.pill {
  padding: var(--space-xs) var(--space-md);
  border-radius: var(--radius-pill);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  border: none;
  background-color: var(--color-pill-bg);
  color: var(--color-text-primary);
  transition: background-color 0.2s, color 0.2s;
}

.pill[disabled] {
  opacity: 0.6;
  cursor: default;
}

.pill.active {
  background-color: var(--color-pill-active-bg);
  color: var(--color-pill-active-text);
}

#itinerary-list {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.day-heading {
  font-size: 16px;
  font-weight: 600;
  margin: 0 0 var(--space-sm) 0;
  color: var(--color-text-secondary);
}

.place-row {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  background-color: var(--color-row-bg);
  border-radius: var(--radius-md);
  padding: var(--space-sm);
  border: 1px solid transparent;
}

.checkbox-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.checkbox-wrapper input[type="checkbox"] {
  width: 20px;
  height: 20px;
  cursor: pointer;
  accent-color: var(--color-text-primary);
}

.place-media {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background-color: #eee;
}

.place-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.place-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.place-name {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.place-meta {
  font-size: 12px;
  color: var(--color-text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.reorder-handle {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  cursor: grab;
  padding: var(--space-xs);
  opacity: 0.5;
}

.reorder-handle[disabled] {
  cursor: default;
  opacity: 0.3;
}

.reorder-handle img {
  pointer-events: none;
}

.action-footer {
  margin-top: var(--space-lg);
  padding-top: var(--space-md);
  border-top: 1px solid var(--color-border);
}

.btn-primary {
  width: 100%;
  padding: var(--space-md);
  font-size: 16px;
  font-weight: 600;
  color: #ffffff;
  background-color: var(--color-text-primary);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
}

.btn-primary[disabled] {
  background-color: var(--color-btn-disabled-bg);
  color: var(--color-btn-disabled-text);
  cursor: not-allowed;
}

completed.responsive:
/* Form and input styling */
input[type="text"],
input[type="number"],
textarea,
select {
  font-family: inherit;
  font-size: inherit;
  color: inherit;
  background-color: transparent;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: var(--space-xs) var(--space-sm);
  width: 100%;
}

input:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-text-primary);
  box-shadow: 0 0 0 2px rgba(17, 17, 17, 0.1);
}

/* Hidden states */
[hidden] {
  display: none !important;
}

/* Status and selected states */
.status-saved {
  color: var(--color-text-secondary);
  font-size: 12px;
  margin-top: var(--space-xs);
  text-align: center;
}

.selected-item {
  background-color: rgba(0, 0, 0, 0.03);
  border-left: 3px solid var(--color-text-primary);
}

/* Keyboard focus visible ring */
:focus-visible {
  outline: 2px solid var(--color-text-primary);
  outline-offset: 2px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Mobile 390px adaptation */
@media (max-width: 390px) {
  #app {
    padding-left: var(--space-sm);
    padding-right: var(--space-sm);
  }

  .place-name {
    font-size: 14px;
  }

  .place-meta {
    font-size: 12px;
  }

  .destination-pills {
    gap: var(--space-xs);
  }

  .pill {
    padding: var(--space-xs) var(--space-sm);
    font-size: 13px;
  }
}

/* Mobile 320px adaptation */
@media (max-width: 320px) {
  .place-row {
    padding: var(--space-xs);
    gap: var(--space-xs);
  }

  .place-media {
    width: 40px;
    height: 40px;
  }

  .place-name {
    font-size: 13px;
  }

  .place-meta {
    font-size: 11px;
  }

  .btn-primary {
    padding: var(--space-sm);
    font-size: 15px;
  }
}
